import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useInAppNavigate } from '@/utils/useInAppNavigate';
import {
  Button,
  FormActions,
  Input,
  SearchInput,
  Card,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import type { ActiveCompanyItem } from '@linm-soft-org/linm-web-common-components';
import { Title, Text, Tag, Space, Spin, Popconfirm } from '@/components/common';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import { createCompanySearchConfig } from '../../../components/search/companySearchConfig';
import { useFpcPermissions } from '../../../utils/fpcPermissionCode';
import { planVoucherListItems, type PlanVoucherDraftDto } from '../../../services/fpc/types';
import {
  processingLevelLabel,
  processingLevelTagColor,
  statusToProcessingLevel,
} from '../CostPlanPage/processingLevel';
import styles from './CostPlanList.module.css';

const TEST_ID = 'cost-plan-list';
const LIST_PATH = '/tc/kh/du-kien-chi';

const formatMoney = (v: number) =>
  new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(v);

function toYmd(iso?: string | null): string {
  if (!iso) return '';
  return iso.slice(0, 10);
}

function formatViDate(iso?: string | null): string {
  const ymd = toYmd(iso);
  if (!ymd) return '—';
  const [y, m, d] = ymd.split('-');
  return `${d}/${m}/${y}`;
}

/** Dự kiến chi theo ngày = phiếu KH lịch Once (1 ngày). */
function isDailyCostPlanVoucher(item: PlanVoucherDraftDto): boolean {
  return (item.planScheduleType || '').toLowerCase() === 'once';
}

const CostPlanList: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useInAppNavigate();
  const now = new Date();
  const { canManageCostPlans, canDeleteCostPlans } = useFpcPermissions();

  const [items, setItems] = useState<PlanVoucherDraftDto[]>([]);
  const [loading, setLoading] = useState(false);
  const [planYear, setPlanYear] = useState(now.getFullYear());
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [branchCode, setBranchCode] = useState('');
  const [selectedCompany, setSelectedCompany] = useState<ActiveCompanyItem | null>(null);
  const [searchText, setSearchText] = useState('');

  const companySearchConfig = useMemo(() => createCompanySearchConfig(), []);

  const fetchList = useCallback(async () => {
    setLoading(true);
    try {
      const pageResult = await fpcService.getPlanVoucherList({
        planYear,
        branchCode: branchCode || undefined,
        search: searchText.trim() || undefined,
        page: 1,
        pageSize: 500,
      });
      let daily = planVoucherListItems(pageResult).filter(isDailyCostPlanVoucher);
      if (fromDate) {
        daily = daily.filter(i => toYmd(i.effectiveFrom) >= fromDate);
      }
      if (toDate) {
        daily = daily.filter(i => toYmd(i.effectiveFrom) <= toDate);
      }
      setItems(daily);
    } catch {
      dispatchAppToast(dispatch, {
        message: 'Không thể tải danh sách dự kiến chi',
        type: 'error',
      });
    } finally {
      setLoading(false);
    }
  }, [dispatch, planYear, branchCode, searchText, fromDate, toDate]);

  useEffect(() => {
    const t = window.setTimeout(() => {
      void fetchList();
    }, 0);
    return () => window.clearTimeout(t);
  }, [fetchList]);

  const handleDelete = async (id: string) => {
    try {
      await fpcService.deletePlanVoucher(id);
      dispatchAppToast(dispatch, { message: 'Đã xóa phiếu dự kiến chi', type: 'success' });
      void fetchList();
    } catch {
      dispatchAppToast(dispatch, { message: 'Lỗi khi xóa phiếu', type: 'error' });
    }
  };

  const handleBranchChange = (item: ActiveCompanyItem | null) => {
    setBranchCode(item?.code ?? item?.id ?? '');
    setSelectedCompany(item);
  };

  return (
    <div className={styles.page} data-testid={`${TEST_ID}-page`}>
      <div className={styles.headerCard}>
        <div className={styles.headerTop}>
          <div>
            <Title level={4}>Dự kiến chi theo ngày</Title>
            <Text type="secondary">Danh sách phiếu dự kiến chi · mức xử lý chứng từ</Text>
          </div>
          <FormActions align="end">
            <Button onClick={() => void fetchList()} data-testid={`${TEST_ID}-refresh-btn`}>
              <i className="fas fa-redo" /> Làm mới
            </Button>
            {canManageCostPlans && (
              <Button
                variant="primary"
                onClick={() => navigate(`${LIST_PATH}/new`)}
                data-testid={`${TEST_ID}-create-btn`}
              >
                <i className="fas fa-plus" /> Tạo mới
              </Button>
            )}
          </FormActions>
        </div>

        <div className={styles.filterRow}>
          <div className={styles.filterField}>
            <label className={styles.filterLabel}>Năm</label>
            <Input
              type="number"
              value={String(planYear)}
              onChange={e => setPlanYear(parseInt(e.target.value, 10) || now.getFullYear())}
              data-testid={`${TEST_ID}-filter-year`}
            />
          </div>
          <div className={styles.filterField}>
            <label className={styles.filterLabel}>Từ ngày</label>
            <Input
              type="date"
              value={fromDate}
              onChange={e => setFromDate(e.target.value)}
              data-testid={`${TEST_ID}-filter-from`}
            />
          </div>
          <div className={styles.filterField}>
            <label className={styles.filterLabel}>Đến ngày</label>
            <Input
              type="date"
              value={toDate}
              onChange={e => setToDate(e.target.value)}
              data-testid={`${TEST_ID}-filter-to`}
            />
          </div>
          <div className={styles.filterFieldWide}>
            <label className={styles.filterLabel}>Chi nhánh</label>
            <SearchInput
              config={companySearchConfig}
              value={branchCode}
              primaryDisplay={selectedCompany?.code}
              secondaryDisplay={selectedCompany?.name}
              onChange={item => handleBranchChange(item as ActiveCompanyItem)}
              onClear={() => handleBranchChange(null)}
              showLabel={false}
              placeholder="Tất cả chi nhánh..."
              data-testid={`${TEST_ID}-filter-branch`}
            />
          </div>
          <div className={styles.filterFieldWide}>
            <label className={styles.filterLabel}>Tìm kiếm</label>
            <Input
              value={searchText}
              onChange={e => setSearchText(e.target.value)}
              placeholder="Số phiếu / diễn giải..."
              data-testid={`${TEST_ID}-filter-search`}
            />
          </div>
        </div>
      </div>

      <Card>
        {loading ? (
          <div className={styles.loading}>
            <Spin /> <Text>Đang tải...</Text>
          </div>
        ) : items.length === 0 ? (
          <div className={styles.empty}>
            <Text type="secondary">Chưa có phiếu dự kiến chi phù hợp bộ lọc</Text>
            {canManageCostPlans && (
              <Button variant="primary" onClick={() => navigate(`${LIST_PATH}/new`)}>
                Tạo phiếu đầu tiên
              </Button>
            )}
          </div>
        ) : (
          <div className={styles.tableWrap}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>Số phiếu</th>
                  <th>Ngày dự kiến</th>
                  <th>Chi nhánh</th>
                  <th>Diễn giải</th>
                  <th className={styles.colRight}>Tổng dự kiến</th>
                  <th className={styles.colRight}>Dòng</th>
                  <th>Mức xử lý</th>
                  <th />
                </tr>
              </thead>
              <tbody>
                {items.map(item => {
                  const level = statusToProcessingLevel(item.status);
                  return (
                    <tr
                      key={item.id}
                      onClick={() => navigate(`${LIST_PATH}/${item.id}`)}
                      className={styles.row}
                      data-testid={`${TEST_ID}-row-${item.id}`}
                    >
                      <td><strong>{item.code}</strong></td>
                      <td>{formatViDate(item.effectiveFrom)}</td>
                      <td>{item.branchCode || '—'}</td>
                      <td>{item.description || '—'}</td>
                      <td className={styles.colRight}>{formatMoney(item.totalPlanned)}</td>
                      <td className={styles.colRight}>{item.lineCount}</td>
                      <td>
                        <Tag color={processingLevelTagColor(level)}>
                          {processingLevelLabel(level)}
                        </Tag>
                      </td>
                      <td onClick={e => e.stopPropagation()}>
                        <Space>
                          <Button size="sm" onClick={() => navigate(`${LIST_PATH}/${item.id}`)}>
                            {canManageCostPlans ? 'Sửa' : 'Xem'}
                          </Button>
                          {canDeleteCostPlans && (
                            <Popconfirm
                              title="Xóa phiếu dự kiến chi này?"
                              onConfirm={() => handleDelete(item.id)}
                            >
                              <Button size="sm">Xóa</Button>
                            </Popconfirm>
                          )}
                        </Space>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </Card>
    </div>
  );
};

export default CostPlanList;
